-- Orbity cross-org reference audit. READ-ONLY. Every row = a reference whose target lives in another org (parent_org set)
-- or does not exist in the row's org (parent_org NULL, soft refs only). Run as postgres/service_role BEFORE migration 034.
WITH findings(kind, child_table, child_col, parent_table, child_id, child_org, parent_org) AS (
  SELECT 'fk','leads','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.leads c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','leads','stage_id','lead_stages', c.id, c.org_id, p.org_id FROM orbity.leads c JOIN orbity.lead_stages p ON p.id=c.stage_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','lead_activities','lead_id','leads', c.id, c.org_id, p.org_id FROM orbity.lead_activities c JOIN orbity.leads p ON p.id=c.lead_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','lead_scoring_results','lead_id','leads', c.id, c.org_id, p.org_id FROM orbity.lead_scoring_results c JOIN orbity.leads p ON p.id=c.lead_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','tasks','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.tasks c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','agenda_events','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.agenda_events c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','reports','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.reports c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','report_snapshots','report_id','reports', c.id, c.org_id, p.org_id FROM orbity.report_snapshots c JOIN orbity.reports p ON p.id=c.report_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','ad_accounts','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.ad_accounts c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','campaigns','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.campaigns c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','campaigns','ad_account_id','ad_accounts', c.id, c.org_id, p.org_id FROM orbity.campaigns c JOIN orbity.ad_accounts p ON p.id=c.ad_account_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','campaign_metrics','campaign_id','campaigns', c.id, c.org_id, p.org_id FROM orbity.campaign_metrics c JOIN orbity.campaigns p ON p.id=c.campaign_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_campaigns','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.content_campaigns c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_posts','campaign_id','content_campaigns', c.id, c.org_id, p.org_id FROM orbity.content_posts c JOIN orbity.content_campaigns p ON p.id=c.campaign_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_posts','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.content_posts c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','post_approvals','post_id','content_posts', c.id, c.org_id, p.org_id FROM orbity.post_approvals c JOIN orbity.content_posts p ON p.id=c.post_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','automation_steps','flow_id','automation_flows', c.id, c.org_id, p.org_id FROM orbity.automation_steps c JOIN orbity.automation_flows p ON p.id=c.flow_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','automation_executions','flow_id','automation_flows', c.id, c.org_id, p.org_id FROM orbity.automation_executions c JOIN orbity.automation_flows p ON p.id=c.flow_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','automation_executions','lead_id','leads', c.id, c.org_id, p.org_id FROM orbity.automation_executions c JOIN orbity.leads p ON p.id=c.lead_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','automation_pending_actions','execution_id','automation_executions', c.id, c.org_id, p.org_id FROM orbity.automation_pending_actions c JOIN orbity.automation_executions p ON p.id=c.execution_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','automation_pending_actions','step_id','automation_steps', c.id, c.org_id, p.org_id FROM orbity.automation_pending_actions c JOIN orbity.automation_steps p ON p.id=c.step_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_plans','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.content_plans c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_plans','campaign_id','content_campaigns', c.id, c.org_id, p.org_id FROM orbity.content_plans c JOIN orbity.content_campaigns p ON p.id=c.campaign_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_plan_items','plan_id','content_plans', c.id, c.org_id, p.org_id FROM orbity.content_plan_items c JOIN orbity.content_plans p ON p.id=c.plan_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_plan_items','task_id','tasks', c.id, c.org_id, p.org_id FROM orbity.content_plan_items c JOIN orbity.tasks p ON p.id=c.task_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','content_plan_items','post_id','content_posts', c.id, c.org_id, p.org_id FROM orbity.content_plan_items c JOIN orbity.content_posts p ON p.id=c.post_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'fk','billing_charges','client_id','clients', c.id, c.org_id, p.org_id FROM orbity.billing_charges c JOIN orbity.clients p ON p.id=c.client_id WHERE p.org_id IS DISTINCT FROM c.org_id
  UNION ALL SELECT 'soft','automation_executions','subject_id(client)','clients', e.id, e.org_id, p.org_id FROM orbity.automation_executions e LEFT JOIN orbity.clients p ON p.id=e.subject_id WHERE e.subject_type='client' AND e.subject_id IS NOT NULL AND p.org_id IS DISTINCT FROM e.org_id
  UNION ALL SELECT 'soft','automation_executions','subject_id(task)','tasks', e.id, e.org_id, p.org_id FROM orbity.automation_executions e LEFT JOIN orbity.tasks p ON p.id=e.subject_id WHERE e.subject_type='task' AND e.subject_id IS NOT NULL AND p.org_id IS DISTINCT FROM e.org_id
  UNION ALL SELECT 'soft','automation_executions','subject_id(meeting)','agenda_events', e.id, e.org_id, p.org_id FROM orbity.automation_executions e LEFT JOIN orbity.agenda_events p ON p.id=e.subject_id WHERE e.subject_type='meeting' AND e.subject_id IS NOT NULL AND p.org_id IS DISTINCT FROM e.org_id
  UNION ALL SELECT 'json','automation_steps','config.stage_id','lead_stages', s.id, s.org_id, p.org_id FROM orbity.automation_steps s LEFT JOIN orbity.lead_stages p ON p.id::text = s.config->>'stage_id' WHERE COALESCE(s.config->>'stage_id','') <> '' AND p.org_id IS DISTINCT FROM s.org_id
  UNION ALL SELECT 'json','automation_flows','trigger_config.stage_id','lead_stages', f.id, f.org_id, p.org_id FROM orbity.automation_flows f LEFT JOIN orbity.lead_stages p ON p.id::text = f.trigger_config->>'stage_id' WHERE COALESCE(f.trigger_config->>'stage_id','') <> '' AND p.org_id IS DISTINCT FROM f.org_id
  UNION ALL SELECT 'user','tasks','assignee_user_id','auth.users', t.id, t.org_id, (SELECT u.org_id FROM public.noctus_users u WHERE u.id=t.assignee_user_id) FROM orbity.tasks t WHERE t.assignee_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noctus_users u WHERE u.id=t.assignee_user_id AND u.org_id=t.org_id) AND NOT EXISTS (SELECT 1 FROM public.org_memberships m WHERE m.user_id=t.assignee_user_id AND m.org_id=t.org_id AND m.status='active')
  UNION ALL SELECT 'user','agenda_events','assignee_user_id','auth.users', t.id, t.org_id, (SELECT u.org_id FROM public.noctus_users u WHERE u.id=t.assignee_user_id) FROM orbity.agenda_events t WHERE t.assignee_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noctus_users u WHERE u.id=t.assignee_user_id AND u.org_id=t.org_id) AND NOT EXISTS (SELECT 1 FROM public.org_memberships m WHERE m.user_id=t.assignee_user_id AND m.org_id=t.org_id AND m.status='active')
  UNION ALL SELECT 'user','content_posts','assignee_user_id','auth.users', t.id, t.org_id, (SELECT u.org_id FROM public.noctus_users u WHERE u.id=t.assignee_user_id) FROM orbity.content_posts t WHERE t.assignee_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noctus_users u WHERE u.id=t.assignee_user_id AND u.org_id=t.org_id) AND NOT EXISTS (SELECT 1 FROM public.org_memberships m WHERE m.user_id=t.assignee_user_id AND m.org_id=t.org_id AND m.status='active')
  UNION ALL SELECT 'user','leads','owner_id','auth.users', t.id, t.org_id, (SELECT u.org_id FROM public.noctus_users u WHERE u.id=t.owner_id) FROM orbity.leads t WHERE t.owner_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noctus_users u WHERE u.id=t.owner_id AND u.org_id=t.org_id) AND NOT EXISTS (SELECT 1 FROM public.org_memberships m WHERE m.user_id=t.owner_id AND m.org_id=t.org_id AND m.status='active')
)
SELECT kind, child_table, child_col, parent_table,
       count(*)                                        AS rows,
       count(*) FILTER (WHERE parent_org IS NULL)      AS dangling,
       (array_agg(child_id ORDER BY child_id))[1:20]   AS sample_child_ids
  FROM findings
 GROUP BY 1,2,3,4
 ORDER BY rows DESC;
